256	    @Override
257	    @Transactional
258	    public void saveOwner(Owner owner) throws DataAccessException {
259	        boolean isNew = owner.isNew();
260	        // Resolve the effective registration date (supplied, or defaulted to the server date) and
261	        // roll it forward to the next business day so it never lands on a weekend. Everything
262	        // derived from the registration date below must use this adjusted value.
263	        LocalDate registrationDate = toBusinessDay(
264	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
265	        owner.setRegistrationDate(registrationDate);
266	        // Whether this owner was accepted into an existing household because the request declared it
267	        // shares one (sharesHousehold). A declared member is deliberately not treated as a suspected
268	        // duplicate below.
269	        boolean declaredHouseholdMember = false;
270	        if (owner.isNew()) {
271	            // The householdId is deterministic: the first 12 hex characters of SHA-256 over
272	            // (normalizedLastName | postcode), so owners with the same last name and postcode share
273	            // it automatically. It is part of the owner's identityKey, so it is resolved first.
274	            owner.setHouseholdId(computeHouseholdId(owner));
275	            // The household is keyed on (last name, postcode), so the members are the existing owners
276	            // sharing both with this owner.
277	            List<Owner> householdMembers = findHouseholdMembers(owner);
278	            // Size of the household after this create: the existing members plus this new owner.
279	            owner.setHouseholdMemberCount(householdMembers.size() + 1);
280	            // A second owner in an existing household is the same household and is rejected as a
281	            // household duplicate, UNLESS the request declares (via sharesHousehold) that it genuinely
282	            // shares the household. sharesHousehold only bypasses this block; it no longer creates the
283	            // link, which is now derived from (last name, postcode).
284	            if (!householdMembers.isEmpty()) {
285	                if (!owner.isSharesHousehold()) {
286	                    throw new HouseholdDuplicateException(owner.getHouseholdId());
287	                }
288	                declaredHouseholdMember = true;
289	            }
290	        }
291	        // Single consolidated duplicate check: reject only when the new owner's WHOLE identityKey
292	        // (normalizedTelephone | email-or-empty | householdId) equals an existing owner's. This
293	        // subsumes the former separate telephone, email and household checks.
294	        if (owner.isNew() && isIdentityKeyAlreadyUsed(owner)) {
295	            throw new DuplicateIdentityException(owner.getIdentityKey());
296	        }
297	        // Soft-match: not a hard identityKey duplicate, but shares an existing owner's last name and
298	        // postcode while carrying a different telephone. Still created, but flagged as a possible
299	        // duplicate pointing at the matching owner. A declared household member is not a suspected
300	        // duplicate, so it is never flagged.
301	        if (owner.isNew() && !declaredHouseholdMember) {
302	            Owner softMatch = findPossibleDuplicate(owner);
303	            if (softMatch != null) {
304	                owner.setPossibleDuplicate(true);
305	                owner.setPossibleDuplicateOf(softMatch.getId());
306	            }
307	        }
308	        if (owner.isNew()
309	            && countOwnersInCity(owner) >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
310	            throw new CityOwnerLimitExceededException(owner.getCity());
311	        }
312	        if (owner.isNew()
313	            && countOwnersRegisteredOn(registrationDate) >= DailyOwnerLimitExceededException.MAX_OWNERS_PER_DAY) {
314	            throw new DailyOwnerLimitExceededException(registrationDate);
315	        }
316	        if (owner.isNew() && owner.getCustomerCode() == null) {
317	            owner.setCustomerCode(generateCustomerCode(owner));
318	        }
319	        if (owner.isNew()) {
320	            owner.setNamesakeCount(countNamesakes(owner));
321	            owner.setBulkSignupWarning(
322	                countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
323	        }
324	        if (owner.getMembershipNumber() == null) {
325	            owner.setMembershipNumber(generateMembershipNumber(owner));
326	        }
327	        ownerRepository.save(owner);
328	        if (isNew) {
329	            AUDIT.info("owner created id={} customerCode={} membershipLevel={} membershipNumber={} registrationDate={}",
330	                owner.getId(), owner.getCustomerCode(), owner.getMembershipLevel(),
331	                owner.getMembershipNumber(), owner.getRegistrationDate());
332	        }
333	    }
334	
335	    /**
336	     * Report whether {@code owner}'s derived {@code identityKey} is already used by any existing
337	     * owner. The key consolidates telephone, email and household into one value, so two owners
338	     * collide only when their whole key is equal (see {@link Owner#getIdentityKey()}). By this point
339	     * the owner's {@code householdId} has been resolved, so its key is complete.
340	     */
341	    private boolean isIdentityKeyAlreadyUsed(Owner owner) {
342	        String identityKey = owner.getIdentityKey();
343	        return ownerRepository.findAll().stream()
344	            .filter(existing -> !existing.isDeleted())
345	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
346	    }
347	
348	    /**
349	     * Find an existing owner this (new) owner soft-matches against: one sharing the same last name
350	     * (compared case-insensitively with collapsed whitespace, like household matching) and the same
351	     * postcode, but carrying a different telephone. Returns the lowest-id such owner, or {@code null}
352	     * when the owner has no last name or postcode to match on, or nothing matches. The caller only
353	     * invokes this once the hard {@code identityKey} duplicate check has already passed.
354	     */
355	    private Owner findPossibleDuplicate(Owner owner) {
356	        String key = householdKey(owner);
357	        if (key == null) {
358	            return null;
359	        }
360	        String telephone = owner.getTelephone();
361	        return ownerRepository.findAll().stream()
362	            .filter(existing -> !existing.isDeleted())
363	            .filter(existing -> key.equals(householdKey(existing))
364	                && !Objects.equals(telephone, existing.getTelephone()))
365	            .min(Comparator.comparing(Owner::getId))
366	            .orElse(null);
367	    }
368	
369	    /**
370	     * Count the owners that already exist (before this create) sharing the same first name and last
371	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
372	     * unique among the existing owners.
373	     */
374	    private int countNamesakes(Owner owner) {
375	        String firstName = owner.getFirstName();
376	        String lastName = owner.getLastName();
377	        if (firstName == null || lastName == null) {
378	            return 0;
379	        }
380	        return (int) ownerRepository.findAll().stream()
381	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
382	                && lastName.equalsIgnoreCase(existing.getLastName()))
383	            .count();
384	    }
385	
386	    /**
387	     * Find the owners that already belong to the same household as {@code owner}, i.e. share both its
388	     * last name and its postcode. Last names are compared case-insensitively with collapsed
389	     * whitespace; postcodes are compared exactly. This is the same keying used by
390	     * {@link #computeHouseholdId(Owner)}, so these are exactly the existing owners that carry the
391	     * owner's computed {@code householdId}. Returns an empty list when the owner has no last name or
392	     * postcode to match on.
393	     */
394	    private List<Owner> findHouseholdMembers(Owner owner) {
395	        String key = householdKey(owner);
396	        if (key == null) {
397	            return List.of();
398	        }
399	        return ownerRepository.findAll().stream()
400	            .filter(existing -> !existing.isDeleted())
401	            .filter(existing -> key.equals(householdKey(existing)))
402	            .toList();
403	    }
404	
405	    /**
406	     * Compute an owner's deterministic {@code householdId}: the first 12 lower-case hex characters of
407	     * SHA-256 over the UTF-8 bytes of {@code normalizedLastName + '|' + postcode} (see
408	     * {@link #householdKey(Owner)}). Owners with the same last name and postcode therefore share the
409	     * same {@code householdId} automatically. Returns {@code null} when the owner has no last name or
410	     * postcode, so it does not belong to a shared household.
411	     */
412	    private String computeHouseholdId(Owner owner) {
413	        String key = householdKey(owner);
414	        return key == null ? null : sha256Hex(key, 6, false);
415	    }
416	
417	    /**
418	     * Build the owner's household key, {@code normalizedLastName + '|' + postcode}, the single value
419	     * that identifies a household. The last name is normalized case-insensitively with collapsed
420	     * whitespace (see {@link #normalizeHouseholdKey}) and the postcode is used exactly as stored.
421	     * Returns {@code null} when the owner has no last name or postcode to key on. This is the shared
422	     * basis for both {@link #computeHouseholdId(Owner)} and household membership matching, so the two
423	     * cannot drift apart.
424	     */
425	    private String householdKey(Owner owner) {
426	        String lastName = normalizeHouseholdKey(owner.getLastName());
427	        String postcode = owner.getPostcode();
428	        if (lastName == null || postcode == null || postcode.isBlank()) {
429	            return null;
430	        }
431	        return lastName + "|" + postcode;
432	    }
433	
434	    /**
435	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
436	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
437	     */
438	    private String normalizeHouseholdKey(String value) {
439	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
440	    }
441	
442	    /**
443	     * Build an owner's {@code customerCode} as {@code '<REGION>-<HASH8>'}: REGION is the region
444	     * code resolved from the owner's postcode (falling back to the owner's city, else
445	     * {@code 'UNKNOWN'}), and HASH8 the first 8 upper-case hex characters of SHA-256 computed over
446	     * the owner's normalized telephone concatenated with the owner's last name (e.g.
447	     * {@code 'NSW-1A2B3C4D'}). There are no per-city sequence numbers; the identity is fully
448	     * derived from the owner's own attributes.
449	     * <p>
450	     * When the derived code collides with an existing owner's {@code customerCode}, a
451	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes it
452	     * unique, so distinct owners always receive distinct customer codes.
453	     */
454	    private String generateCustomerCode(Owner owner) {
455	        String base = PostcodeRules.resolveRegion(owner.getPostcode(), owner.getCity()) + "-" + customerHash(owner);
456	        return deduplicateCustomerCode(base);
457	    }
458	
459	    /**
460	     * Return {@code base} when no existing owner already uses it as their {@code customerCode};
461	     * otherwise append {@code '-<n>'} with the smallest {@code n} of 2 or more that is not already
462	     * taken (counting both the bare {@code base} and any earlier {@code '-<n>'} de-duplications).
463	     */
464	    private String deduplicateCustomerCode(String base) {
465	        Set<String> existing = ownerRepository.findAll().stream()
466	            .map(Owner::getCustomerCode)
467	            .filter(Objects::nonNull)
468	            .collect(Collectors.toSet());
469	        if (!existing.contains(base)) {
470	            return base;
471	        }
472	        int n = 2;
473	        while (existing.contains(base + "-" + n)) {
474	            n++;
475	        }
476	        return base + "-" + n;
477	    }
478	
479	    /**
480	     * Compute the hash segment of an owner's {@code customerCode}: the first 8 upper-case hex
481	     * characters of SHA-256 over the UTF-8 bytes of the owner's normalized telephone concatenated
482	     * with the owner's last name.
483	     */
484	    private String customerHash(Owner owner) {
485	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
486	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
487	        return sha256Hex(telephone + lastName, 4, true);
488	    }
489	
490	    /**
491	     * Compute the leading hex of SHA-256 over the UTF-8 bytes of {@code input}: the first
492	     * {@code bytes} bytes of the digest rendered as {@code 2 * bytes} hex characters, upper-case when
493	     * {@code upperCase} is {@code true}, otherwise lower-case. Shared by the derived identifiers that
494	     * are built from a SHA-256 prefix (e.g. the household id and the customer-code hash), so the
495	     * digest handling and the "SHA-256 not available" error live in one place.
496	     */
497	    private String sha256Hex(String input, int bytes, boolean upperCase) {
498	        byte[] digest;
499	        try {
500	            digest = MessageDigest.getInstance("SHA-256")
501	                .digest(input.getBytes(StandardCharsets.UTF_8));
502	        } catch (NoSuchAlgorithmException e) {
503	            throw new IllegalStateException("SHA-256 is required but not available", e);
504	        }
505	        String format = upperCase ? "%02X" : "%02x";
506	        StringBuilder hex = new StringBuilder(bytes * 2);
507	        for (int i = 0; i < bytes; i++) {
508	            hex.append(String.format(format, digest[i]));
509	        }
510	        return hex.toString();
511	    }
512	
513	    /**
514	     * Count the owners that already exist (before this create) in the same city as {@code owner},
515	     * compared case-insensitively.
516	     */
517	    private long countOwnersInCity(Owner owner) {
518	        String city = owner.getCity();
519	        return ownerRepository.findAll().stream()
520	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
521	            .count();
522	    }
523	
524	    /**
525	     * Count the owners that already exist (before this create) whose {@code registrationDate} falls
526	     * on the given {@code date}. Used to enforce the per-day create cap.
527	     */
528	    private long countOwnersRegisteredOn(LocalDate date) {
529	        return ownerRepository.findAll().stream()
530	            .filter(existing -> date.equals(existing.getRegistrationDate()))
531	            .count();
532	    }
533	
534	    /**
535	     * Fixed public holidays that registration dates must never fall on. Together with weekends these
536	     * are the non-business days skipped by {@link #toBusinessDay(LocalDate)}.
537	     */
538	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
539	        LocalDate.parse("2026-01-01"),
540	        LocalDate.parse("2026-01-26"),
541	        LocalDate.parse("2026-04-25"),
542	        LocalDate.parse("2026-12-25"),
543	        LocalDate.parse("2026-12-28"));
544	
545	    /**
546	     * Roll {@code date} forward to the next business day, skipping weekends (Saturday and Sunday) and
547	     * the fixed {@link #PUBLIC_HOLIDAYS public holidays}. A date already on a business day is returned
548	     * unchanged. Registration dates are required to fall on a business day.
549	     */
550	    private LocalDate toBusinessDay(LocalDate date) {
551	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
552	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
553	            || PUBLIC_HOLIDAYS.contains(date)) {
554	            date = date.plusDays(1);
555	        }
556	        return date;
557	    }
558	
559	    /**
560	     * Build an owner's {@code membershipNumber} as {@code '<customerCode>-M<YY>'}, where YY is the
561	     * last two digits of the fiscal year of the owner's business-day-adjusted
562	     * {@code registrationDate} (the fiscal year starting 1 July), e.g. {@code 'NSW-1A2B3C4D-M27'}.
563	     */
564	    private String generateMembershipNumber(Owner owner) {
565	        String yy = String.format("%02d", Owner.fiscalYearOf(owner.getRegistrationDate()) % 100);
566	        return String.format("%s-M%s", owner.getCustomerCode(), yy);
567	    }
